CREATE VIEW player_season_averages AS
SELECT 
    p.player_id,
    p.name AS player_name,
    t.team_name,
    ps.games_played,
    ps.points AS avg_points,
    ps.assist AS avg_assists,
    ps.steal AS avg_steals,
    ps.block AS avg_blocks,
    ps.field_goal_percent AS fg_percent,
    ps.three_point_percent AS three_fg_percent,
    ps.free_throw_percent AS ft_percent
FROM player_stats ps
JOIN player p ON ps.player_id = p.player_id
JOIN team t ON p.team_id = t.team_id;


CREATE VIEW team_season_summary AS
SELECT 
    t.team_id,
    t.team_name,
    ts.win,
    ts.loss,
    ts.points AS avg_points,
    ts.field_goal_percent AS fg_percent,
    ts.three_point_percent AS three_fg_percent,
    ts.free_throw_percent AS ft_percent
FROM team_stats ts
JOIN team t ON ts.team_id = t.team_id;

CREATE VIEW player_contract_summary AS
SELECT 
    p.name AS player_name,
    t.team_name,
    c.salary,
    pos.position_name AS position
FROM contracts c
JOIN player p ON c.position_id = p.position_id AND c.team_id = p.team_id
JOIN team t ON c.team_id = t.team_id
JOIN positions pos ON c.position_id = pos.position_id;

CREATE INDEX idx_player_name ON player(name);

CREATE INDEX idx_team_points_wins ON team_stats(points, win);

CREATE INDEX idx_team_salary ON contracts(team_id, salary);

CREATE SEQUENCE team_stats_log_seq
START WITH 1
INCREMENT BY 1
NOCACHE;

CREATE TABLE team_stats_log (
    log_id INTEGER PRIMARY KEY,
    team_id VARCHAR2(3),
    updated_on DATE DEFAULT SYSDATE,
    old_wins INTEGER,
    new_wins INTEGER,
    old_losses INTEGER,
    new_losses INTEGER
);

CREATE OR REPLACE TRIGGER track_win_loss_updates
AFTER UPDATE OF win, loss ON team_stats
FOR EACH ROW
BEGIN
    INSERT INTO team_stats_log (
        log_id,
        team_id,
        updated_on,
        old_wins,
        new_wins,
        old_losses,
        new_losses
    )
    VALUES (
        team_stats_log_seq.NEXTVAL,
        :NEW.team_id,
        SYSDATE,
        :OLD.win,
        :NEW.win,
        :OLD.loss,
        :NEW.loss
    );
END;
